<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useHomepageStore } from '@/stores/homepage';
import FeaturedProducts from '@/components/guest/FeaturedProducts.vue';
import ProductCard from '@/components/common/ProductCard.vue';
import MorningCountNotice from '@/components/common/MorningCountNotice.vue';
import bannerApi from '@/api/banner';
import { productApi, storeApi } from '@/api';
import { useAuthStore } from '@/stores/auth';
import { formatPrice } from '@/utils/format';
import { homepageRanking, homepageRecommendationChips, homepageRecommendations, newHomepageProducts, signatureHomepageProduct } from '@/utils/homepageCommerce';
import deliveryStoryImage from '@/assets/images/fastguy-delivery-story.jpg';

const homepageStore = useHomepageStore();
const auth = useAuthStore();
const currentSlide = ref(0);
const carouselPaused = ref(false);
const reduceMotion = ref(false);
const categories = ref([]);
const invalidCategoryImages = ref(new Set());
const storeName = ref('FastGuy');
const storeAddress = ref('');
const morningCountNotice = ref(null);
const mapEmbedUrl = computed(() => storeAddress.value ? `https://www.google.com/maps?q=${encodeURIComponent(storeAddress.value)}&output=embed` : '');
const mapOpenUrl = computed(() => storeAddress.value ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(storeAddress.value)}` : '');
const fallbackImage = 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 700"%3E%3Crect width="1200" height="700" fill="%231b1714"/%3E%3Ccircle cx="900" cy="350" r="250" fill="%23f26a2e" fill-opacity=".18"/%3E%3C/svg%3E';
const fallbackSlides = [
  { title: 'Món ngon cho mọi cuộc vui', subtitle: 'Chọn món bạn thích, đặt nhanh và tận hưởng một bữa ăn trọn vị.', cta: 'Chọn món ngay', link: '/menu', image: fallbackImage },
  { title: 'Bữa ngon không cần phải chờ', subtitle: 'Thực đơn rõ ràng, món dễ chọn và hành trình đơn hàng luôn trong tầm mắt.', cta: 'Khám phá thực đơn', link: '/menu', image: fallbackImage },
];
const banners = ref(fallbackSlides);
const activeSlide = computed(() => banners.value[currentSlide.value] || fallbackSlides[0]);
const signatureProduct = computed(() => signatureHomepageProduct(homepageStore.bestSellers));
const recommendationChips = computed(() => homepageRecommendationChips(homepageStore.bestSellers));
const activeRecommendation = ref('');
const recommendedProducts = computed(() => homepageRecommendations(homepageStore.bestSellers, activeRecommendation.value || recommendationChips.value[0]?.key));
const rankingProducts = computed(() => homepageRanking(homepageStore.bestSellers).slice(0, 5));
const newProducts = computed(() => newHomepageProducts(homepageStore.bestSellers));
const activeReview = ref(0);
const currentReview = computed(() => homepageStore.featuredReviews[activeReview.value]);
let slideInterval;
let motionQuery;

function listFrom(data) { return Array.isArray(data) ? data : data?.items || data?.content || data?.data || []; }
function hideCategoryImage(id) { invalidCategoryImages.value = new Set([...invalidCategoryImages.value, id]); }
function categoryIcon(name) {
  const value = String(name || '').toLocaleLowerCase('vi');
  if (value.includes('gà')) return 'bi-fire';
  if (value.includes('burger') || value.includes('bánh')) return 'bi-circle-square';
  if (value.includes('uống') || value.includes('nước')) return 'bi-cup-straw';
  if (value.includes('kèm') || value.includes('khoai')) return 'bi-box2-heart';
  return 'bi-grid';
}
function navigateSlide(index) { currentSlide.value = index; startCarousel(); }
function stopCarousel() { clearInterval(slideInterval); slideInterval = undefined; }
function startCarousel() { stopCarousel(); if (!reduceMotion.value && !carouselPaused.value && banners.value.length > 1) slideInterval = setInterval(() => { currentSlide.value = (currentSlide.value + 1) % banners.value.length; }, 5000); }
function setPaused(value) { carouselPaused.value = value; value ? stopCarousel() : startCarousel(); }
function updateMotion(event) { reduceMotion.value = event.matches; startCarousel(); }
function selectRecommendation(key) { activeRecommendation.value = key; }
function closeMorningNotice() { if (morningCountNotice.value?.stableKey) localStorage.setItem(`fastguy-notice:${morningCountNotice.value.stableKey}`, new Date().toLocaleDateString('en-CA')); morningCountNotice.value = null; }
function moveReview(offset) {
  const count = homepageStore.featuredReviews.length;
  if (count) activeReview.value = (activeReview.value + offset + count) % count;
}

onMounted(async () => {
  motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  reduceMotion.value = motionQuery.matches;
  motionQuery.addEventListener('change', updateMotion);
  homepageStore.load();
  const [bannerResult, categoryResult, storeResult] = await Promise.allSettled([bannerApi.getActive(), productApi.getCategories(), storeApi.getConfig()]);
  if (bannerResult.status === 'fulfilled') banners.value = bannerResult.value?.length ? bannerResult.value : fallbackSlides;
  if (categoryResult.status === 'fulfilled') categories.value = listFrom(categoryResult.value).map(item => ({ id: item.categoryId, name: item.name, imageUrl: item.imageUrl || '' })).filter(item => item.id && item.name).slice(0, 6);
  if (storeResult.status === 'fulfilled') {
    storeName.value = String(storeResult.value?.storeName || 'FastGuy').trim();
    storeAddress.value = String(storeResult.value?.storeAddress || '').trim();
    const notice = storeResult.value?.morningCountNotice;
    if (notice?.stableKey && localStorage.getItem(`fastguy-notice:${notice.stableKey}`) !== new Date().toLocaleDateString('en-CA')) morningCountNotice.value = notice;
  }
  currentSlide.value = 0;
  startCarousel();
});
onBeforeUnmount(() => { stopCarousel(); motionQuery?.removeEventListener('change', updateMotion); });
</script>

<template>
  <div class="home-page">
    <MorningCountNotice :notice="morningCountNotice" @close="closeMorningNotice" />
    <section class="hero signature-hero" aria-labelledby="signature-title">
      <div class="hero-glow" aria-hidden="true"></div>
      <div class="hero-shell">
        <div class="hero-copy">
          <p class="hero-eyebrow"><i class="bi bi-fire" aria-hidden="true"></i> FastGuy signature</p>
          <h1 id="signature-title">{{ signatureProduct ? 'Bữa ngon cho ngày bận rộn.' : activeSlide.title }}</h1>
          <p class="hero-desc">{{ signatureProduct?.description || activeSlide.subtitle }}</p>
          <div v-if="signatureProduct" class="signature-product">
            <strong>{{ signatureProduct.name }}</strong>
            <span class="signature-price">{{ formatPrice(signatureProduct.price) }}</span>
            <span class="signature-proof"><i class="bi bi-star-fill" aria-hidden="true"></i> {{ Number(signatureProduct.averageRating || 0).toFixed(1) }} · {{ Number(signatureProduct.soldCount || 0).toLocaleString('vi-VN') }} đã bán</span>
          </div>
          <div class="hero-actions">
            <router-link :to="signatureProduct ? `/product/${signatureProduct.productId}` : (activeSlide.link || '/menu')" class="hero-btn">{{ signatureProduct ? 'Chọn món này' : (activeSlide.cta || 'Chọn món ngay') }} <i class="bi bi-arrow-up-right" aria-hidden="true"></i></router-link>
            <router-link to="/menu" class="hero-secondary">Xem thực đơn</router-link>
          </div>
        </div>
        <div class="hero-visual">
          <div class="hero-image-wrap"><img :src="signatureProduct?.image || activeSlide.imageUrl || activeSlide.image" :alt="signatureProduct?.name || activeSlide.title" width="900" height="720"></div>
          <span class="hero-stamp" aria-hidden="true">FAST<br>GUY</span>
          <div class="hero-note"><i class="bi bi-lightning-charge-fill" aria-hidden="true"></i><span><strong>{{ signatureProduct ? 'Được chọn nhiều nhất' : 'Đặt nhanh' }}</strong>{{ signatureProduct ? signatureProduct.name : 'Chọn món rõ ràng' }}</span></div>
        </div>
      </div>
    </section>
    <section class="promo-strip" aria-label="Ưu đãi FastGuy"><div class="container"><span>Ưu đãi hôm nay</span><strong>{{ activeSlide.title }}</strong><router-link :to="activeSlide.link || '/menu'">{{ activeSlide.cta || 'Khám phá' }} <i class="bi bi-arrow-right" aria-hidden="true"></i></router-link><div v-if="banners.length > 1" class="promo-controls"><button aria-label="Ưu đãi trước" @click="navigateSlide((currentSlide - 1 + banners.length) % banners.length)"><i class="bi bi-arrow-left"></i></button><button aria-label="Ưu đãi tiếp theo" @click="navigateSlide((currentSlide + 1) % banners.length)"><i class="bi bi-arrow-right"></i></button></div></div></section>

    <section v-if="categories.length" class="quick-categories" aria-labelledby="quick-category-title">
      <div class="container quick-category-shell">
        <div><p>Chọn nhanh</p><h2 id="quick-category-title">Bạn muốn ăn gì hôm nay?</h2></div>
        <nav class="category-list" aria-label="Danh mục món ăn">
          <router-link v-for="category in categories" :key="category.id" class="category-card" :to="{ path: '/menu', query: { category: category.id } }"><span class="category-image"><img v-if="category.imageUrl && !invalidCategoryImages.has(category.id)" :src="category.imageUrl" :alt="category.name" loading="lazy" @error="hideCategoryImage(category.id)"><span v-else class="category-image-fallback"><span class="category-icon"><i :class="`bi ${categoryIcon(category.name)}`" aria-hidden="true"></i></span></span></span><strong>{{ category.name }}</strong><span class="category-arrow"><i class="bi bi-arrow-up-right" aria-hidden="true"></i></span></router-link>
        </nav>
      </div>
    </section>

    <FeaturedProducts :products="homepageStore.bestSellers" :loading="homepageStore.loading" :error="homepageStore.error" @retry="homepageStore.retry" />



    <section v-if="recommendationChips.length" class="commerce-section recommendations" aria-labelledby="recommendation-title">
      <div class="container"><div class="commerce-head"><p>Chọn theo khẩu vị</p><h2 id="recommendation-title">Hôm nay ăn gì?</h2><span>Chọn theo tâm trạng của bạn.</span></div>
        <div class="recommendation-tabs" role="tablist" aria-label="Kiểu bữa ăn"><button v-for="chip in recommendationChips" :key="chip.key" role="tab" :aria-selected="(activeRecommendation || recommendationChips[0]?.key) === chip.key" :class="{ active: (activeRecommendation || recommendationChips[0]?.key) === chip.key }" @click="selectRecommendation(chip.key)">{{ chip.label }}</button></div>
        <TransitionGroup name="food-fade" tag="div" class="recommendation-grid"><ProductCard v-for="product in recommendedProducts" :key="product.productId" :product="product" homepage /></TransitionGroup>
      </div>
    </section>

    <section v-if="newProducts.length" class="commerce-section new-products" aria-labelledby="new-products-title"><div class="container"><div class="commerce-head commerce-head-row"><div><p>Vừa có mặt</p><h2 id="new-products-title">Mới lên bếp</h2><span>Những hương vị mới trong thực đơn.</span></div><router-link to="/menu">Xem tất cả <i class="bi bi-arrow-right" aria-hidden="true"></i></router-link></div><div class="recommendation-grid"><ProductCard v-for="product in newProducts" :key="product.productId" :product="product" homepage /></div></div></section>

    <section v-if="rankingProducts.length" class="commerce-section trending" aria-labelledby="trending-title"><div class="container"><div class="commerce-head"><p>Lựa chọn nổi bật</p><h2 id="trending-title">Đang được yêu thích</h2><span>Những món nổi bật theo lượt đặt thực tế.</span></div><ol class="ranking-list"><li v-for="(product, index) in rankingProducts" :key="product.productId"><router-link :to="`/product/${product.productId}`"><b>{{ String(index + 1).padStart(2, '0') }}</b><div><strong>{{ product.name }}</strong><span><i class="bi bi-star-fill" aria-hidden="true"></i> {{ Number(product.averageRating || 0).toFixed(1) }} · {{ product.reviewCount || 0 }} đánh giá · {{ Number(product.soldCount || 0).toLocaleString('vi-VN') }} đã bán</span></div><em>{{ formatPrice(product.price) }}</em><i class="bi bi-arrow-up-right" aria-hidden="true"></i></router-link></li></ol></div></section>

    <section class="brand-manifesto" aria-labelledby="manifesto-title"><div class="container manifesto-shell"><div class="manifesto-copy"><p class="chapter-label">01 / Câu chuyện</p><h2 id="manifesto-title">Bận không có nghĩa là ăn qua loa.</h2><blockquote>“Cuộc sống có thể vội. Bữa ăn thì không.”</blockquote><p>Có những ngày bạn chạy từ việc này sang việc khác, một bữa ăn cũng trở thành thứ dễ bị bỏ quên nhất. FastGuy được tạo ra cho những ngày như vậy: để dù bạn chỉ có ít thời gian, bữa ăn vẫn có thể ngon và tử tế.</p></div><figure class="manifesto-visual"><img :src="deliveryStoryImage" alt="Nhân viên FastGuy giao bữa ăn cho khách hàng" loading="lazy" width="1024" height="1280"></figure></div></section>

    <section class="making-story" aria-labelledby="making-title"><div class="container"><p class="chapter-label">02 / Cách FastGuy làm</p><div class="making-head"><h2 id="making-title">Nhanh ở việc đặt. Không vội ở việc làm món.</h2><p>Bạn chỉ mất vài phút để đặt món. Trong bếp, từng bước cần thiết vẫn được thực hiện để món ăn đến tay bạn đúng như nó nên có.</p></div><ol><li><b>01</b><strong>Nguyên liệu mỗi ngày</strong><span>Chuẩn bị sẵn sàng cho giờ phục vụ.</span></li><li><b>02</b><strong>Làm khi có đơn</strong><span>Món bắt đầu sau khi bạn lựa chọn.</span></li><li><b>03</b><strong>Kiểm tra và đóng gói</strong><span>Rà soát lựa chọn trước khi rời bếp.</span></li></ol></div></section>

    <section class="people-time" aria-labelledby="people-title"><div class="container people-shell"><div class="people-intro"><p class="chapter-label">03 / Con người &amp; thời gian</p><h2 id="people-title">Có người đứng sau mỗi món ăn.</h2><p>Có người chuẩn bị nguyên liệu, đứng bếp và kiểm tra từng phần trước khi món ăn rời cửa hàng.</p></div><div class="people-copy"><blockquote>Nhanh để bạn không phải sống vội.</blockquote><p>FastGuy lo phần bữa ăn, để bạn dành thời gian cho những điều quan trọng hơn.</p></div></div></section>

    <section class="account-prompt"><div class="container"><div class="account-panel"><div><p>{{ auth.isUser ? `Chào ${auth.user?.fullName || 'bạn'}` : '04 / Bữa ăn tiếp theo' }}</p><h2>{{ auth.isUser ? 'Tiếp tục hành trình món ngon của bạn.' : 'Hôm nay bạn muốn ăn gì?' }}</h2><span>{{ auth.isUser ? 'Những món bạn từng thích, những đơn hàng bạn muốn xem lại.' : 'Không cần suy nghĩ quá lâu. Chọn món, FastGuy lo phần còn lại.' }}</span></div><div class="account-actions"><router-link v-if="auth.isUser" to="/account/orders">Lịch sử đơn <i class="bi bi-arrow-right" aria-hidden="true"></i></router-link><router-link v-if="auth.isUser" to="/account/favorites" class="secondary">Món yêu thích</router-link><router-link v-else to="/menu">Khám phá thực đơn <i class="bi bi-arrow-right" aria-hidden="true"></i></router-link></div></div></div></section>

    <section v-if="currentReview" class="commerce-section reviews" aria-labelledby="reviews-title"><div class="container review-shell"><div class="review-copy"><div class="commerce-head"><p>Trải nghiệm thật</p><h2 id="reviews-title">Khách hàng nói gì</h2></div><blockquote>“{{ currentReview.comment }}”</blockquote><div class="review-meta"><span aria-label="Đánh giá 5 sao"><i v-for="star in currentReview.rating" :key="star" class="bi bi-star-fill" aria-hidden="true"></i></span><strong>{{ currentReview.userName }}</strong></div><div v-if="homepageStore.featuredReviews.length > 1" class="review-controls"><button aria-label="Đánh giá trước" @click="moveReview(-1)"><i class="bi bi-arrow-left" aria-hidden="true"></i></button><span>{{ activeReview + 1 }} / {{ homepageStore.featuredReviews.length }}</span><button aria-label="Đánh giá tiếp theo" @click="moveReview(1)"><i class="bi bi-arrow-right" aria-hidden="true"></i></button></div></div></div></section>

    <section v-if="storeAddress" class="store-location" aria-labelledby="store-location-title"><div class="container location-shell"><div class="location-copy"><p>Tìm FastGuy</p><h2 id="store-location-title">Ghé cửa hàng gần bạn</h2><div class="location-address"><i class="bi bi-geo-alt-fill" aria-hidden="true"></i><div><strong>{{ storeName }}</strong><span>{{ storeAddress }}</span></div></div><a :href="mapOpenUrl" target="_blank" rel="noopener noreferrer">Mở trong Google Maps <i class="bi bi-arrow-up-right" aria-hidden="true"></i></a></div><div class="location-map"><iframe :src="mapEmbedUrl" :title="`Bản đồ ${storeName}`" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div></div></section>

  </div>
</template>

<style scoped>
